53|// Strict parse at the trust boundary: exact fields only, so a client
54|// bug cannot silently spend budget on a misread request.
55|export function parseImageRequest(json: unknown): ImageRequest {
56|  if (!isRecord(json)) throw new ImageValidationError();
57|  const { kind } = json;
58|  // The token is single-use proof, never part of imageKey.
59|  if (
60|    json.turnstileToken !== undefined &&
61|    (typeof json.turnstileToken !== "string" || json.turnstileToken.length > 2048)
62|  ) {
63|    throw new ImageValidationError();
64|  }
65|  const token = typeof json.turnstileToken === "string" ? json.turnstileToken : undefined;
66|  if (kind === "passage") {
67|    const keys = Object.keys(json).sort().join(",");
68|    if (
69|      keys !== "bookId,kind,n,textVersion" &&
70|      keys !== "bookId,kind,n,style,textVersion" &&
71|      keys !== "bookId,endN,kind,n,textVersion" &&
72|      keys !== "bookId,endN,kind,n,style,textVersion" &&
73|      keys !== "bookId,kind,n,textVersion,turnstileToken" &&
74|      keys !== "bookId,kind,n,style,textVersion,turnstileToken" &&
75|      keys !== "bookId,endN,kind,n,textVersion,turnstileToken" &&
76|      keys !== "bookId,endN,kind,n,style,textVersion,turnstileToken"
77|    ) {
78|      throw new ImageValidationError();
79|    }
80|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
81|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
82|      throw new ImageValidationError();
83|    }
84|    if (typeof json.n !== "number" || !Number.isInteger(json.n)) throw new ImageValidationError();
85|    const endN = json.endN;
86|    if (endN !== undefined && (typeof endN !== "number" || !Number.isInteger(endN))) {
87|      throw new ImageValidationError();
88|    }
89|    const style = parseStyleChoice(json.style);
90|    return {
91|      kind: "passage",
92|      bookId: json.bookId,
93|      textVersion: json.textVersion,
94|      n: json.n,
95|      ...(endN === undefined ? {} : { endN }),
96|      ...(style === undefined ? {} : { style }),
97|      ...(token === undefined ? {} : { turnstileToken: token }),
98|    };
99|  }
100|  if (kind === "scene") {
101|    const keys = Object.keys(json).sort().join(",");
102|    if (
103|      keys !== "bookId,kind,sceneId,textVersion" &&
104|      keys !== "bookId,kind,sceneId,style,textVersion" &&
105|      keys !== "bookId,kind,sceneId,textVersion,turnstileToken" &&
106|      keys !== "bookId,kind,sceneId,style,textVersion,turnstileToken"
107|    ) {
108|      throw new ImageValidationError();
109|    }
110|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
111|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
112|      throw new ImageValidationError();
113|    }
114|    if (typeof json.sceneId !== "string" || json.sceneId.length === 0) throw new ImageValidationError();
