116|    return {
117|      kind: "scene",
118|      bookId: json.bookId,
119|      textVersion: json.textVersion,
120|      sceneId: json.sceneId,
121|      ...(style === undefined ? {} : { style }),
122|      ...(token === undefined ? {} : { turnstileToken: token }),
123|    };
124|  }
125|  if (kind === "chapter") {
126|    const keys = Object.keys(json).sort().join(",");
127|    if (
128|      keys !== "bookId,ch,kind,reachedCh,textVersion" &&
129|      keys !== "bookId,ch,kind,reachedCh,style,textVersion" &&
130|      keys !== "bookId,ch,kind,reachedCh,textVersion,turnstileToken" &&
