249|// The illustration style line, shared by scene and chapter prompts: Oz
250|// keeps the Denslow sentence by default, the parsed style's descriptor
251|// otherwise; other books get the generic period-faithful line.
252|export function styleLine(style: ImageStyle | undefined, book?: StyleBook): string {
253|  if (style !== undefined) return styleDescriptorLine(style, book);
254|  if (book === undefined || book.id === "oz") {
255|    return (
256|      "Illustration in the style of W. W. Denslow's 1900 first-edition " +
257|      "illustrations for The Wonderful Wizard of Oz: flat color, bold black " +
258|      "ink outlines, limited palette. Dorothy wears silver shoes. Nothing " +
259|      "from the 1939 MGM film, no ruby slippers, no film look. No text, " +
260|      "no captions, no lettering in the image."
261|    );
262|  }
263|  const title = cleanBookField(book.title);
264|  const author = cleanBookField(book.author);
265|  return (
266|    `Classic book illustration for ${title} by ${author}: ink and watercolor, ` +
