272|// Base prompt from trusted server-side book text only. The client sends
273|// ordinals and ids, never free text, so there is no injection path. Only
274|// the optional parsed style reaches the prompt, never raw client text.
275|// The route appends validated, clipped model-derived bookmap details after this base.
276|export function buildPrompt(args: {
277|  kind: Exclude<ImageKind, "chapter">;
278|  passageText: string;
279|  sceneTitle: string;
280|  sceneClip: string;
281|  style?: ImageStyle;
282|  book?: StyleBook;
283|}): string {
284|  const style = styleLine(args.style, args.book);
285|  if (args.kind === "scene") {
286|    return (
287|      `Scene "${args.sceneTitle}". ${clipText(args.sceneClip, MAX_SCENE_CLIP_CHARS)}. ${style}`
288|    );
289|  }
290|  return (
291|    `Scene "${args.sceneTitle}". Passage: ${clipText(args.passageText, MAX_PASSAGE_CHARS)}. ` +
292|    `Context: ${clipText(args.sceneClip, MAX_SCENE_CLIP_CHARS)}. ${style}`
293|  );
