296|export function buildCaption(args: {
297|  kind: ImageKind;
298|  sceneTitle: string;
299|  passageText: string;
300|}): string {
301|  if (args.kind === "scene" || args.kind === "chapter") return args.sceneTitle;
302|  const words = args.passageText.replace(/\s+/g, " ").trim().split(" ").slice(0, 10);
303|  const head = words.join(" ");
304|  return words.length >= 10 ? `${head}…` : head;
