25|// The denslow descriptor is unused: denslow parses to undefined, so the
26|// prompt and key stay exactly as today.
27|export type ImageStylePresetId = (typeof IMAGE_STYLE_PRESETS)[number]["id"];
28|
29|export const DEFAULT_IMAGE_STYLE = "denslow" as const;
30|
31|// Skin ids are owned by app/skin.ts. Pencil and chihiro get their own
32|// presets rather than reusing "pencil" or "anime", so images already cached
33|// under those style keys keep matching their old prompt.
34|export const SKIN_DEFAULT_IMAGE_STYLE: Readonly<Partial<Record<string, ImageStylePresetId>>> = {
35|  engraving: "denslow",
36|  watercolor: "watercolor",
37|  ink: "pen-pencil",
38|  comic: "comic",
39|  pencil: "graphite",
40|  chihiro: "lantern-dusk",
41|};
