159|export interface BookRef {
160|  id: string;
161|  textVersion: string;
162|  paragraphNs: Set<number>;
163|  sceneIds: Set<string>;
164|  chapters: Set<number>;
165|}
166|
167|// Checks the parsed request against the frozen book text.
168|export function validateAgainstBook(req: ImageRequest, book: BookRef): void {
169|  if (req.bookId !== book.id) throw new ImageValidationError();
170|  if (req.textVersion !== book.textVersion) throw new ImageValidationError();
171|  if (req.kind === "passage") {
172|    if (!book.paragraphNs.has(req.n)) throw new ImageValidationError();
173|    if (req.endN !== undefined && (req.endN < req.n || !book.paragraphNs.has(req.endN))) {
174|      throw new ImageValidationError();
175|    }
176|    return;
177|  }
178|  if (req.kind === "scene") {
179|    if (!book.sceneIds.has(req.sceneId)) throw new ImageValidationError();
180|    return;
181|  }
182|  if (!book.chapters.has(req.ch)) throw new ImageValidationError();
183|  if (!book.chapters.has(req.reachedCh) || req.ch > req.reachedCh) {
184|    throw new ImageValidationError();
185|  }
186|}
187|
188|// One paragraph maps to one image; one scene maps to one image; one
189|// chapter maps to one comic page. A styled image keeps the same base with
190|// a style segment before the file name, so an omitted style keys
191|// byte-identically to today. A multi-paragraph passage keeps pN when endN
192|// is absent or equals n, so old images keep hitting; a wider range gets
193|// pN-M.
194|export function imageKey(req: ImageRequest): string {
195|  const base = `images/${req.bookId}/${req.textVersion}/${PROMPT_VERSION}`;
196|  const file =
197|    req.kind === "passage"
198|      ? req.endN === undefined || req.endN === req.n
199|        ? `p${req.n}.webp`
200|        : `p${req.n}-${req.endN}.webp`
201|      : req.kind === "scene"
202|        ? `scene-${req.sceneId}.webp`
203|        : `chapter-${req.ch}-${CHAPTER_PROMPT_VERSION}.webp`;
204|  return req.style === undefined ? `${base}/${file}` : `${base}/${styleSegment(req.style)}/${file}`;
205|}
