89|export interface PassageRequest {
90|  kind: "passage";
91|  bookId: string;
92|  textVersion: string;
93|  n: number;
94|  endN?: number;
95|  style?: ImageStyle;
96|  // Single-use proof, never part of the cache key.
97|  turnstileToken?: string;
98|}
99|
100|export interface SceneRequest {
101|  kind: "scene";
102|  bookId: string;
103|  textVersion: string;
104|  sceneId: string;
105|  style?: ImageStyle;
106|  // Single-use proof, never part of the cache key.
107|  turnstileToken?: string;
108|}
109|
110|// Minimal store surface the route needs; server modules and tests
111|// implement it. Lives here so server and core share one shape.
112|export interface KV {
113|  get(key: string): Promise<string | null>;
114|  setNxEx(key: string, value: string, exSec: number): Promise<boolean>;
115|  set(key: string, value: string): Promise<void>;
116|  incr(key: string): Promise<number>;
117|  incrBy(key: string, by: number): Promise<number>;
118|  decr(key: string): Promise<number>;
119|  decrBy(key: string, by: number): Promise<number>;
120|  expire(key: string, sec: number): Promise<void>;
121|  releaseIfToken(key: string, token: string): Promise<boolean>;
122|}
123|
124|export interface ChapterRequest {
125|  kind: "chapter";
126|  bookId: string;
127|  textVersion: string;
128|  ch: number;
129|  // Furthest chapter the reader has reached. Client-claimed, so it stops
130|  // casual spoilers and direct pre-generation of later chapters, not a
131|  // determined client.
132|  reachedCh: number;
133|  style?: ImageStyle;
134|  // Single-use proof, never part of the cache key.
135|  turnstileToken?: string;
136|}
137|
138|export type ImageRequest = PassageRequest | SceneRequest | ChapterRequest;
139|
140|export type ImageErrorCode = "quota" | "budget" | "daily_budget" | "human" | "unavailable" | "bad_request";
141|
142|export type ImageResponse =
143|  | { status: "ready"; url: string; cached: boolean; caption: string }
144|  | { status: "pending" }
145|  | { status: "error"; code: ImageErrorCode; message: string };
146|
147|export const PROMPT_VERSION = "v4" as const;
148|
149|// Chapter pages version their prompt apart from scenes and passages, so a
150|// prompt change never touches the other keys.
151|export const CHAPTER_PROMPT_VERSION = "c4" as const;
152|
153|// shortcut: USD 0.01 per image per the spike, revisit if Meta reprices.
154|export const IMAGE_COST_MICRO = 10000 as const;
155|
156|export interface ChatMessage {
157|  role: "user" | "assistant";
158|  text: string;
159|}
160|
161|// Chat API contract. Server builds context from the book text up to
162|// positionN (whole book when spoilerMode), prefix first, question last.
163|export interface ChatRequest {
164|  bookId: string;
165|  textVersion: string;
166|  positionN: number;
167|  spoilerMode: boolean;
168|  messages: ChatMessage[];
169|}

