4|
5|function scenes(n: number): { id: string; summary: string }[] {
6|  return Array.from({ length: n }, (_, i) => ({
7|    id: `s${i + 1}`,
8|    summary: `The friends meet a wonder in scene ${i + 1}, and Dorothy laughs with joy.`,
9|  }));
10|}
11|
12|describe("chapterPanels", () => {
13|  it("keeps one panel per scene at 6 or fewer", () => {
14|    for (const n of [1, 5, 6]) {
