1|// Pure range logic for passage-picture reuse: an overlapping selection
2|// reuses a cached picture, a much larger or smaller one gets its own.
3|import { imageKey } from "./images";
4|import type { PassageRequest } from "./types";
5|
6|export interface ParaRange {
7|  start: number;
8|  end: number;
9|}
10|
11|// Reuse a cached picture when |A∩B|/|A∪B| over paragraphs is at least
12|// this: a selection extended by a paragraph above and below ([5] vs
13|// [4,6]) shares a picture, one covering three times the text or more
14|// gets its own.
15|export const REUSE_JACCARD = 1 / 3;
16|
17|// Bounds the per-scene lookup.
18|export const MAX_RANGES_PER_SCENE = 24;
19|
20|export function jaccard(a: ParaRange, b: ParaRange): number {
21|  const inter = Math.max(0, Math.min(a.end, b.end) - Math.max(a.start, b.start) + 1);
22|  const union = a.end - a.start + 1 + (b.end - b.start + 1) - inter;
23|  return union <= 0 ? 0 : inter / union;
24|}
25|
26|export function pickReusable(cached: readonly ParaRange[], want: ParaRange): ParaRange | null {
27|  let best: ParaRange | null = null;
28|  let bestScore = 0;
29|  for (const c of cached) {
30|    const score = jaccard(c, want);
31|    if (score >= REUSE_JACCARD && score > bestScore) {
32|      best = c;
33|      bestScore = score;
34|    }
35|  }
36|  return best;
37|}
38|
39|// Parses the stored range list; drops garbage entries, never throws.
40|export function parseRanges(raw: string | null): ParaRange[] {
41|  if (!raw) return [];
42|  let parsed: unknown;
43|  try {
44|    parsed = JSON.parse(raw);
45|  } catch {
46|    return [];
47|  }
48|  if (!Array.isArray(parsed)) return [];
49|  const out: ParaRange[] = [];
50|  for (const item of parsed) {
51|    if (typeof item !== "object" || item === null || Array.isArray(item)) continue;
52|    const { start, end } = item as Record<string, unknown>;
53|    if (typeof start !== "number" || !Number.isInteger(start)) continue;
54|    if (typeof end !== "number" || !Number.isInteger(end)) continue;
55|    if (end < start) continue;
56|    out.push({ start, end });
57|  }
58|  return out;
59|}
60|
61|export function addRange(list: readonly ParaRange[], r: ParaRange): ParaRange[] {
62|  if (list.some((e) => e.start === r.start && e.end === r.end)) return [...list];
63|  return [...list, r].slice(-MAX_RANGES_PER_SCENE);
64|}
65|
66|// The scene's range list lives next to its images; built from imageKey's
67|// directory so the two never drift.
68|export function rangeListKeyFor(req: PassageRequest, sceneId: string): string {
69|  const key = imageKey(req);
70|  return `img:ranges:${key.slice(0, key.lastIndexOf("/"))}/${sceneId}`;
71|}

